function l(n,t){return n<=0||t<=0?0:t===1?n:n*(1+t/30)}var i=.01;function o(n,t,r){if(!t.length)return null;if(n==="TIME"||n==="BODYWEIGHT"){let e=Math.max(...t.map(u=>u.reps));return r.reps>e?{kind:"reps",value:r.reps,previous:e}:null}if(r.weight<=0||r.reps<=0)return null;let s=Math.max(...t.map(e=>e.weight));if(r.weight>s+i)return{kind:"weight",value:r.weight,previous:s};let p=t.filter(e=>Math.abs(e.weight-r.weight)<i);if(p.length){let e=Math.max(...p.map(u=>u.reps));if(r.reps>e)return{kind:"reps_at_weight",value:r.reps,previous:e}}let h=Math.max(...t.map(e=>l(e.weight,e.reps))),m=l(r.weight,r.reps);return m>h+i?{kind:"e1rm",value:Math.round(m*10)/10,previous:Math.round(h*10)/10}:null}export{l as a,o as b};
